    export const getStockOpsControllerCellsStockUrl = (warehouseId: string,
    params: StockOpsControllerCellsStockParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/warehouses/${warehouseId}/cells-stock?${stringifiedParams}` : `/api/warehouses/${warehouseId}/cells-stock`
}

